-- =============================================
-- Rent Manager Database Schema & Migration SQL
-- Target: Cloudflare D1 / SQLite
-- =============================================
PRAGMA foreign_keys = OFF;

DROP TABLE IF EXISTS checkout_logs;
DROP TABLE IF EXISTS rent_bills;
DROP TABLE IF EXISTS tenants;
DROP TABLE IF EXISTS rooms;
DROP TABLE IF EXISTS admins;

CREATE TABLE admins (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    username    TEXT NOT NULL UNIQUE,
    password    TEXT NOT NULL,
    created_at  DATETIME DEFAULT (datetime('now', 'localtime')),
    updated_at  DATETIME DEFAULT (datetime('now', 'localtime'))
);
CREATE TABLE rooms (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    room_no         TEXT NOT NULL UNIQUE,
    base_rent       REAL NOT NULL,
    base_deposit    REAL NOT NULL DEFAULT 0,
    electric_price  REAL NOT NULL DEFAULT 1.0,
    water_price     REAL NOT NULL DEFAULT 4.5,
    status          TEXT NOT NULL DEFAULT 'occupied',
    note            TEXT,
    created_at      DATETIME DEFAULT (datetime('now', 'localtime'))
);
CREATE TABLE tenants (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id         INTEGER REFERENCES rooms(id),
    room_no         TEXT NOT NULL,
    name            TEXT NOT NULL,
    is_primary      INTEGER NOT NULL DEFAULT 1,
    gender          TEXT NOT NULL DEFAULT 'unknown',
    phone           TEXT,
    id_card         TEXT,
    address         TEXT,
    move_in_date    DATE NOT NULL,
    move_out_date   DATE,
    status          TEXT NOT NULL DEFAULT 'active',
    created_at      DATETIME DEFAULT (datetime('now', 'localtime'))
);
CREATE TABLE rent_bills (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    bill_no         TEXT UNIQUE,
    room_id         INTEGER REFERENCES rooms(id),
    room_no         TEXT NOT NULL DEFAULT '',
    tenant_id       INTEGER REFERENCES tenants(id),
    tenant_names    TEXT NOT NULL DEFAULT '',
    period_start    DATE,
    period_end      DATE,
    paid_at         DATE NOT NULL,
    renew_date      DATE,
    rent_amount     REAL NOT NULL,
    electric_start  REAL NOT NULL DEFAULT 0,
    electric_end    REAL NOT NULL DEFAULT 0,
    electric_price  REAL NOT NULL DEFAULT 1.0,
    electric_usage  REAL NOT NULL DEFAULT 0,
    electric_fee    REAL NOT NULL DEFAULT 0,
    water_start     REAL NOT NULL DEFAULT 0,
    water_end       REAL NOT NULL DEFAULT 0,
    water_price     REAL NOT NULL DEFAULT 4.5,
    water_usage     REAL NOT NULL DEFAULT 0,
    water_fee       REAL NOT NULL DEFAULT 0,
    broadband_fee   REAL NOT NULL DEFAULT 0,
    ev_charge_fee   REAL NOT NULL DEFAULT 0,
    other_fee       REAL NOT NULL DEFAULT 0,
    total_amount    REAL NOT NULL,
    is_collected    INTEGER NOT NULL DEFAULT 0,
    pay_method      TEXT DEFAULT 'wechat',
    note            TEXT,
    created_at      DATETIME DEFAULT (datetime('now', 'localtime'))
);
CREATE TABLE checkout_logs (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id         INTEGER REFERENCES rooms(id),
    room_no         TEXT NOT NULL,
    tenant_id       INTEGER REFERENCES tenants(id),
    checkout_date   DATE NOT NULL,
    deposit_amount  REAL NOT NULL,
    deduct_rent     REAL DEFAULT 0,
    deduct_utility  REAL DEFAULT 0,
    deduct_damage   REAL DEFAULT 0,
    refund_amount   REAL NOT NULL,
    note            TEXT,
    created_at      DATETIME DEFAULT (datetime('now', 'localtime'))
);

